{
  "technical_and_design_decisions": [
    "For the Solo ordering process (U4): Use a single-threaded goroutine to consume transactions from a buffered channel, implement an in-memory append-only ledger with a seek index mapping client IDs to their last processed transaction sequence to support disconnection/reconnection.",
    "For the standalone Fabric CLI (U8): Decouple CLI command logic from peer node internal packages by extracting shared command definitions into a separate Go module, use Go's native cross-compilation to generate platform-specific binaries with no external dependencies (e.g., no RocksDB requirement).",
    "For the state cache (U6): Implement a thread-safe LRU cache keyed by block number and state key, with automatic invalidation when a new block is committed to ensure cache consistency with the ledger state.",
    "For the chaincode friendly name feature (U1): Store the friendly name as part of the chaincode definition in the channel configuration, expose the name via peer CLI query commands and Fabric SDKs for application developers.",
    "For the lifecycle system chaincode (U2): Reuse the existing Fabric ACL (Access Control List) framework to enforce permissions for deployment policy management operations, avoiding the need to build new access control logic.",
    "For the public GitHub mirror (U5): Configure the GitHub repo as a read-only mirror of the existing Gerrit-hosted Fabric repo, with automated sync and CI pipelines that run the existing Fabric test suite on all pull requests.",
    "For the centralized documentation (U7): Use the Docusaurus static site generator (already used by other Hyperledger projects) for the centralized docs site to ensure consistency with existing Hyperledger documentation, with full-text search enabled via Algolia.",
    "For upgrade flow documentation (U3): Include sample configuration files, common error troubleshooting steps, and links to relevant Fabric lifecycle commands to make the documentation actionable for developers."
  ],
  "assumptions": [
    "The existing Hyperledger Fabric codebase (hosted on Gerrit) is the source of truth for all code changes, and the development team has full access to the Gerrit repo for implementation work.",
    "For the Solo orderer (U4), the existing Fabric block creation and validation logic can be reused, with only the consensus and ledger components modified to support the single-process, in-memory design.",
    "For the standalone CLI (U8), existing peer CLI command logic can be refactored and reused without full rewrites, minimizing development effort for command functionality.",
    "For the state cache (U6), the cache is an optional, configurable feature that does not require changes to existing chaincode execution or endorsement logic, only integration with the rw-set builder component.",
    "For the GitHub mirror (U5), the Hyperledger governance team has approved the public mirror, and no legal or licensing barriers exist to hosting the Fabric code on GitHub.",
    "For the centralized documentation (U7), existing Fabric documentation content can be migrated to the new site with minimal rewrites, and other Hyperledger projects are willing to contribute their docs to the centralized site.",
    "For the Solo orderer (U4), the in-memory ledger does not need to persist data across orderer restarts, as it is intended for development and testing use cases only.",
    "All user stories are independent, with no cross-dependencies that would require rework of completed work for other user stories."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Implement chaincode friendly name feature",
      "activity_description": "Add friendly name field to chaincode definition metadata, update peer CLI and SDKs to support setting and querying the name, add unit and integration tests for the feature",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A2",
      "activity_name": "Extend lifecycle system chaincode for deployment policy management",
      "activity_description": "Add new lifecycle SCC APIs for deployment policy CRUD operations, integrate with existing ACL framework for access control, update peer CLI commands to interact with the new APIs, add tests for policy management workflows",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A3",
      "activity_name": "Write and publish upgrade flow documentation",
      "activity_description": "Create step-by-step guides for chaincode and channel upgrade processes, include sample configs and troubleshooting content, integrate documentation into the centralized Hyperledger docs site",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A4",
      "activity_name": "Implement Solo ordering process",
      "activity_description": "Design and implement in-memory ledger with seek index, build single-threaded block creation from buffered transaction channel, add client disconnection/reconnection support with history retrieval, add tests for Solo orderer functionality",
      "most_likely_effort": 48
    },
    {
      "activity_id": "A5",
      "activity_name": "Set up public GitHub mirror for Fabric code",
      "activity_description": "Configure read-only GitHub mirror of Gerrit-hosted Fabric repo, set up CI/CD pipelines to run tests on GitHub PRs, add contributing guidelines and README for GitHub users, validate mirror sync functionality",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A6",
      "activity_name": "Implement state cache for rw-set building",
      "activity_description": "Design and implement thread-safe LRU state cache, integrate cache with rw-set builder component, add configuration toggle for cache enable/disable, add unit and performance tests for cache functionality",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A7",
      "activity_name": "Consolidate Hyperledger documentation on hyperledger.org",
      "activity_description": "Set up centralized Docusaurus documentation site, migrate existing Hyperledger project docs to the new site, add search and navigation functionality, test site usability across platforms",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A8",
      "activity_name": "Develop standalone cross-platform Fabric CLI tool",
      "activity_description": "Refactor peer CLI commands to decouple from peer internal dependencies, build standalone CLI binary with no external dependencies, create cross-compilation scripts for Mac/Windows, add installation and usage docs, test binaries on target platforms",
      "most_likely_effort": 40
    }
  ],
  "reported_total": {
    "most_likely_effort": 216
  }
}

